#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int A, B;
    if (scanf("%d %d", &A, &B) != 2) return 0;

    int *a = malloc((size_t)A * sizeof(int));
    if (a == NULL) return 0;

    for (int i = 0; i < A; i++) {
        scanf("%d", &a[i]);
    }

    int pos = 0;
    for (int i = 0; i < B; i++) {
        int y;
        scanf("%d", &y);

        while (pos < A && a[pos] != y) {
            pos++;
        }

        if (pos < A) {
            pos++;
        } else {
            printf("N\n");
            free(a);
            return 0;
        }
    }

    printf("S\n");
    free(a);
    return 0;
}
